import{_ as t,o as n,c as i,az as a,aZ as o}from"./chunks/framework.DXXa9EJF.js";const g=JSON.parse('{"title":"Teeinblue Integration","description":"","frontmatter":{},"headers":[],"relativePath":"teeinblue/index.md","filePath":"teeinblue/index.md"}'),l={name:"teeinblue/index.md"};function r(s,e,u,d,p,m){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="teeinblue-integration" tabindex="-1">Teeinblue Integration <a class="header-anchor" href="#teeinblue-integration" aria-label="Permalink to “Teeinblue Integration”">​</a></h1><p>ImagenHub is a standalone AI model management application. While it features native integration with Teeinblue, it functions independently to manage and optimize AI image generation workflows.</p><p><img src="'+o+'" alt="ImagenHub overview"></p><p>It provides advanced control over AI models through the following features:</p><ul><li><strong>Multi-Model Templates</strong> — Assign specific models and prompts to individual templates, allowing you to run multiple AI models simultaneously.</li><li><strong>Prompt Security</strong> — Prompts are secured within the data structure and completely hidden from client-side console inspection.</li><li><strong>Flexible API Access</strong> — Connect your own model API keys or use an ImagenHub subscription for built-in model access.</li><li><strong>Fail-Safe Redundancy</strong> — If a custom API key runs out of tokens, the system automatically falls back to ImagenHub&#39;s network to ensure uninterrupted image generation.</li></ul><p>This section walks you through connecting ImagenHub to Teeinblue and setting up your first AI workflow.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li><a href="/teeinblue/api-keys">Create an API key</a> and paste it into Teeinblue.</li><li><a href="/teeinblue/model-access">Choose how to power your models</a> — your own provider keys, or an ImagenHub subscription.</li><li><a href="/teeinblue/templates">Build a template</a> — pick a model, write a prompt, test the output.</li><li><a href="/teeinblue/integration">Wire the template into Teeinblue</a> on a Photo Upload Layer.</li></ol>',8)])])}const h=t(l,[["render",r]]);export{g as __pageData,h as default};
